  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
  if RenderedEndsWith(generated, "<<") {
    // Decide whether to enter constrained mode or treat this << as free text.
    // Enter constrained mode if: at least one >> has already closed a span,
    // OR we have generated enough tokens to be near the final answer.
    var closedSpans := CSDHelpers.CountTokenOccurrences(generated, ">>");
    var genLen := |generated|;
    if closedSpans >= 1 || genLen >= 60 {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
    // else: treat this << as free intermediate text; Phase 1 continues.
  }
}

// Phase 2: constrained expression generation with dead-end recovery.
// Reserve 1 step for post-loop close by stopping at maxSteps - 1.
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  // Dead-end detection: if very few valid tokens remain, recover.
  var isDeadEnd := helpers.DeadEndDetection(parser, currentConstrainedOut, 2);
