    if parser.IsCompletePrefix(currentConstrainedOut) {
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else {
      // Cannot recover to a complete prefix; exit constrained mode without
      // emitting >>. The open << remains in generated but we prefer this
      // to an infinite ! flood.
      insideConstrainedOut := false;
      currentConstrainedOut := [];
      // No step consumed.
    }
  } else {
    // Normal constrained step.
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    var aG, aI, aC := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
    generated := aG;
    insideConstrainedOut := aI;
    currentConstrainedOut := aC;
  }
}

// Post-loop: close the span if it is complete and budget remains.
if insideConstrainedOut && parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
  var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + 1;
}

cost := steps;

